///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_searchByCorpList_OnFilter
 * @description search By Corp List On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_searchByCorpList_OnFilter = function(row) {
    try {
        lst_gubun = rdo_gubun.getValue();
        f3 = dts_searchByCorpList.getCellData(row, "LIST_STAT_CD");
        if (scwin.skw !== "") {
            f1 = dts_searchByCorpList.getCellData(row, "COM_ABBRV");
            f2 = dts_searchByCorpList.getCellData(row, "OLD_COM_ABBRV");
            if (lst_gubun === 0) {
                if (f1.indexOf(scwin.skw) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else if (f2.indexOf(scwin.skw) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else {
                    return false;
                }
            } else {
                if (f1.indexOf(scwin.skw) !== -1 && f3.indexOf(lst_gubun) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else if (f2.indexOf(scwin.skw) !== -1 && f3.indexOf(lst_gubun) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else {
                    return false;
                }
            }
        } else {
            if (lst_gubun === 0) {
                scwin.filter_cnt++;
                return true;
            } else if (f3.indexOf(lst_gubun) !== -1) {
                scwin.filter_cnt++;
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34200.dts_searchByCorpList_OnFilter" });
    }
};

