scwin.cmb_HandOverEmpList_onselchange2 = async function() {
    try {
        scwin.grd_HandOverIsuList_nm = dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "EMP_NM");
        if (cmb_HandOverEmpList.getSelectedIndex() !== cmb_TakeOverEmpList.getSelectedIndex()) {
            await scwin.listBycorpusr1();
        } else {
            if (cmb_HandOverEmpList.getSelectedIndex() !== -1 && cmb_TakeOverEmpList.getSelectedIndex() !== -1) {
                await $c.win.alert("인계인과 인수인을 동일하게 지정하셨습니다.");
                cmb_HandOverEmpList.setSelectedIndex(scwin.tmpIdx1);
            }
        }
        scwin.tmpIdx1 = cmb_HandOverEmpList.getSelectedIndex();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34200.cmb_HandOverEmpList_onselchange2" });
    }
};

