    try {
        // alert('grd_allByCorpList.OnCheckClick('+col+','+ colid+','+ bCheck+')');

        if (bCheck !== 0) {
            if (cmb_chgEmpList.getSelectedIndex() === -1) {
                await $c.win.alert("담당자를 먼저 선택하여주십시요.");
                dts_allByCorpList.setCellData(col, "CHK_FLAG", 0);
                return;
            }
            if (dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "USR_ID") === dts_allByCorpList.getCellData(col, "INTEG_USR_ID")) {
                await $c.win.alert("우측에 이미 선택되어진 담당자의 종목입니다.");
                dts_allByCorpList.setCellData(col, "CHK_FLAG", 0);
            }
            // fn_change_stock();

            // alert('MxGrid_1.OnCheckClick('+col+','+ colid+','+ bCheck+')');

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34200.grd_allByCorpList_oncheckclick" });
    }
};

/**
 * @method
 * @name grd_HandOverIsuList_onheadcheckclick
 * @description grd_HandOverIsuList onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_HandOverIsuList_onheadcheckclick = function(col, colid, bCheck) {
    try {
        let gcnt = dts_HandOverIsuList.getRowCount();
        if (gcnt > 0) {
            grd_HandOverIsuList.Redraw = false;
            dts_HandOverIsuList.setBroadcast(false);
            for (let i = 1; i <= gcnt; i++) {
                dts_HandOverIsuList.setCellData(i, "CHK_FLAG", bCheck);
            }
            dts_HandOverIsuList.setBroadcast(true, true);
            grd_HandOverIsuList.Redraw = true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34200.grd_HandOverIsuList_onheadcheckclick" });
    }
};

