/**
 * @method
 * @name listUsrSync
 * @description 담당자 목록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listUsrSync = async function() {

    // 담당자간 인수인계 - 인계인 선택
    const sbmOptions = {
        id : "sbm_dts_HandOverEmpList",
        action : "/PFInfo.do",
        ref : "",
        target : "dts_HandOverEmpList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자간 인수인계 - 인수인 선택
    const sbmOptions2 = {
        id : "sbm_dts_TakeOverEmpList",
        action : "/PFInfo.do",
        ref : "",
        target : "dts_TakeOverEmpList=body.content",
        isProcessMsg : false
    };

