/**
 * @method
 * @name allHandOver
 * @description ---------------------------------------------------------------------------- 일괄 인수인계 처리 -------------------------------------------------------------------------------
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allHandOver = async function() {
    // 일괄처리
    scwin.gubun = 1;
    const rowcnt = dts_HandOverIsuList.getRowCount();
    if (rowcnt === 0) {
        await $c.win.alert("처리할 사항이 없습니다.");
        return;
    }
    let msg = $c.stf.getMessageParam("MSG-A006", "일괄인계");
    let res = window.confirm(msg);
    if (res) {
        if (await scwin.chkDupDisign(dts_HandOverIsuList)) {
            await $c.win.alert("한 회사에 대해 같은날 두번 이상 담당자 변경을 할 수 없습니다.\n관리자에게 문의 하십시오.");
            return;
        }
        dts_Save.setBroadcast(false);
        for (let i = 1; i <= dts_HandOverIsuList.getRowCount(); i++) {
            dts_Save.insertRow();
            dts_Save.setCellData(i, "ISUR_CD", dts_HandOverIsuList.getCellData(i, "ISUR_CD"));
            dts_Save.setCellData(i, "PRE_USR_ID", dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(i, "PRE_DEP_CD", dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "DEP_CD"));
            dts_Save.setCellData(i, "AF_USR_ID", dts_TakeOverEmpList.getCellData(cmb_TakeOverEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(i, "AF_DEP_CD", dts_TakeOverEmpList.getCellData(cmb_TakeOverEmpList.getSelectedIndex() + 1, "DEP_CD"));
        }
        dts_Save.setBroadcast(true, true);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/PFInfo.do",
            ref : "dts_Save",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

