    }
    if (sval === "all") {
        t_msg = "일괄해제";
        dts_Save.setBroadcast(false);
        for (let i = 1; i <= dts_chgByCorpList.getRowCount(); i++) {
            dts_Save.insertRow();
            dts_Save.setCellData(tmpInt, "ISUR_CD", dts_chgByCorpList.getCellData(i, "ISUR_CD"));
            dts_Save.setCellData(tmpInt, "PRE_USR_ID", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(tmpInt, "PRE_DEP_CD", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "DEP_CD"));
            tmpInt++;
        }
        dts_Save.setBroadcast(true, true);
    } else {
        t_msg = "선택해제";
        if (!scwin.cntDatasetRowCheck(dts_chgByCorpList)) {
            await $c.win.alert("변경하실 종목 목록중 체크사항이 없습니다.");
            return;
        } else {
            dts_Save.setBroadcast(false);
            for (let i = 1; i <= dts_chgByCorpList.getRowCount(); i++) {
                if (dts_chgByCorpList.getCellData(i, "CHK_FLAG") === 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "ISUR_CD", dts_chgByCorpList.getCellData(i, "ISUR_CD"));
                    dts_Save.setCellData(tmpInt, "PRE_USR_ID", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "USR_ID"));
                    dts_Save.setCellData(tmpInt, "PRE_DEP_CD", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "DEP_CD"));
