/**
 * @method
 * @name getQuery
 * @description 초기화인 경우 alert 표시 안되도록.
 * @param {String} srcUrl srcUrl
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.getQuery = function(srcUrl, id) {
    if (srcUrl.indexOf("?") < 0) return "";
    const queryStr = srcUrl.split("?")[1];
    const val = queryStr.split("&");
    for (let i = 0; i < val.length; i++) {
        const tmp = val[i].split("=");
        if (id === tmp[0]) {
            return tmp[1];
        }
    }
    return "";
};

/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getParam = async function() {
    const parentWin = $c.frame.path("../");
    // alert("[frame.srcUrl]"+frame.srcUrl);
    scwin.gBizTpCd = $c.stf.getQuery(frame.srcUrl, "src");
    // alert("[gBizTpCd]"+gBizTpCd);

    if (scwin.gBizTpCd === 'STK') {
        scwin.gLdMktTpCd = "1";
        scwin.gUpDepCd = "2600";
    } else if (scwin.gBizTpCd === 'KSQ') {
        scwin.gLdMktTpCd = "2";
        scwin.gUpDepCd = "3400";
    } else if (scwin.gBizTpCd === 'KNX') {
        scwin.gLdMktTpCd = "6";
        scwin.gUpDepCd = "3B00";
    } else if (scwin.gBizTpCd === 'ETF') {
        scwin.gLdMktTpCd = "1";
        scwin.gUpDepCd = "2B00";
        scwin.gETFYn = "Y";
        scwin.gSecugrpId = 'EF';
    } else if (scwin.gBizTpCd === 'PF') {
        scwin.gLdMktTpCd = "1";
        scwin.gUpDepCd = "2B00";
        scwin.gPFYn = "Y";
        scwin.gSecugrpId = 'PF';
    } else {
        await $c.win.alert('파라미터값 확인 오류');
    }
};

/**
 * @method
 * @name alert_error3
 * @description alert error3 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error3 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j).substring(0, 220));
        }
    }
};

/**
 * @method
 * @name setGrid
 * @description set Grid 처리
 * @returns {void}
 * @hidden N
 */
scwin.setGrid = function() {
    if (scwin.gLdMktTpCd === "2" || scwin.gLdMktTpCd === '6') {
        $c.cm.setColumnProp(grd_HandOverIsuList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_TakeOverIsuList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_nonByCorpList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_byCorpList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_allByCorpList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_chgByCorpList, "SECT_TP_NM", "Show", true);
