/**
 * @method
 * @name todat
 * @description todat 처리
 * @returns {void}
 * @hidden N
 */
scwin.todat = function() {
    // alert('[InfoMenuID]'+InfoMenuID());
    scwin.todat = $c.ut.cGetToday("yyyymmdd");
};

/**
 * @method
 * @name cntDatasetRowCheck
 * @description ---------------------------------------------------------------------------- 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. -------------------------------------------------------------------------------
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntDatasetRowCheck = function(sval) {
    cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name chkDupDisign
 * @description 한날에 두번 담당자 변경을 하느냐.
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkDupDisign = async function(obj) {
    let isDup = false;
    for (let i = 1; i <= obj.getRowCount(); i++) {
        if (obj.getCellData(i, "CHK_FLAG") === 1) {
            if (obj.getCellData(i, "ASSGN_STRT_DD") === scwin.todat) {
                await $c.win.alert("'" + obj.getCellData(i, "COM_ABBRV") + "' 는(은)  금일 이미 변경 하셨습니다.");
                isDup = true;
            }
        }
    }
    return isDup;
};

/**
 * @method
 * @name stockAdd
 * @description 미지정 종목 추가
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stockAdd = async function() {
    // 미지정 종목 추가
    if (!scwin.cntDatasetRowCheck(dts_nonByCorpList)) {
        await $c.win.alert("추가할 종목의  체크사항이 없습니다.");
    } else {
        scwin.isInit = false;
        await scwin.canDesign();
    }
};

/**
 * @method
 * @name getCheckedIsurCd
 * @description get Checked Isur Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCheckedIsurCd = function() {
    let tmpInt = 1;
    scwin.gubun = 2;
    let isur_cds = "";
    dts_Save.setBroadcast(false);
    for (let i = 1; i <= dts_nonByCorpList.getRowCount(); i++) {
        if (dts_nonByCorpList.getCellData(i, "CHK_FLAG") === 1) {
            dts_Save.insertRow();
            dts_Save.setCellData(tmpInt, "ISUR_CD", dts_nonByCorpList.getCellData(i, "ISUR_CD"));
            dts_Save.setCellData(tmpInt, "AF_USR_ID", dts_byCorpEmpList.getCellData(cmb_byCorpEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(tmpInt, "AF_DEP_CD", dts_byCorpEmpList.getCellData(cmb_byCorpEmpList.getSelectedIndex() + 1, "DEP_CD"));
            isur_cds = isur_cds + dts_nonByCorpList.getCellData(i, "ISUR_CD") + ",";
            tmpInt++;
        }
    }
    dts_Save.setBroadcast(true, true);
    return isur_cds;
};

/**
 * @method
 * @name checkUndesignAction
 * @description cnt:0기 지정된 이력없음. 1: 선택한 한목중 지정된 이력이 있는게 하나라도 있음.
 * @param {Number} cnt cnt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkUndesignAction = async function(cnt) {
    if (cnt === 0) {
        await scwin.doUndesignAction();
    } else {
        const _com_abbrv = mdsUndesign.getCellData(1, "COM_ABBRV");
        const _isur_cd = mdsUndesign.getCellData(1, "ISUR_CD");
        const _emp_nm = mdsUndesign.getCellData(1, "EMP_NM");
        await $c.win.alert('지정 할 대상중에 기 지정된 건이 존재합니다.\n확인 후 다시 지정하세요.\n[' + _com_abbrv + "(" + _isur_cd + ") 담당자:" + _emp_nm + "]");
        await scwin.resetdts_Save();
        await scwin.listBycorpusr3();
        await scwin.listNodesign();
    }
};

