 */
scwin.JongmokSearch = function() {
    scwin.skw = (txb_ComNm.getValue()).toUpperCase();
    if (scwin.skw === "") {
        // true를 먼저 안해주면 false가 안먹네...
        dts_searchByCorpList.UseFilter = "true";
        dts_searchByCorpList.Filter();
        dts_searchByCorpList.UseFilter = "false";
        dts_searchByCorpList.setRowPosition(1, 0);
    } else {
        dts_searchByCorpList.UseFilter = "true";
        dts_searchByCorpList.Filter();
        dts_searchByCorpList.setRowPosition(1, 0);
    }
};

